self.KB_CONTENT["card:755949"]={"id":"card:755949","ty":"card","sourceId":"755949","title":"『新客戶申請建立作業』的作業目的為何？","ver":"iGP","topic":"客戶","keywords":["客戶","電子","簽核","透過"],"y":"explain","answer":"透過建立新客戶的建立作業，可更嚴謹的走審核與確認流程，才將資料寫入客戶基本資料檔中，並可串接電子簽核系統。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
