self.KB_CONTENT["card:755127"]={"id":"card:755127","ty":"card","sourceId":"755127","title":"『客戶別商品出貨排程表』中的『分類方式 (C 10)』為何？","ver":"iGP","topic":"客戶","keywords":["客戶","分類","出貨","直接"],"y":"other","answer":"* 共用參數設定作業中的「商品分類方式一」、「商品分類方式二」、「商品分類方式三」及「商品分類方式四」之四種方式，欄位非空白者所對應的設定資料，將於此選項直接顯示出欄位資料。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
