self.KB_CONTENT["card:783586"]={"id":"card:783586","ty":"card","sourceId":"783586","title":"『資金預估明細表』中的『僅列印存款餘額不足之日 (C1)』為何？","ver":"GP4以上","topic":"明細表","keywords":["明細表","餘額","資金","存款"],"y":"other","answer":"* 預設N。* 勾選時，表列印可用資金餘額小於零之資料。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
