self.KB_CONTENT["card:779349"]={"id":"card:779349","ty":"card","sourceId":"779349","title":"『進貨單驗收作業(IDL)』的作業目的為何？","ver":"GP4以上","topic":"進貨單","keywords":["進貨單","驗收"],"y":"explain","answer":"晶圓進貨採三階段式收料(收料、驗收、成本)時，進貨驗收之動作由此作業執行。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
