self.KB_CONTENT["field:792070"]={"id":"field:792070","ty":"field","sourceId":"792070","title":"選擇資產類別","ver":"GP4以上","topic":"","keywords":[],"job":"設備保修工時成本明細表","code":"MA001","answer":"* 可按(icon)或[F2]資產類別查詢，選擇欲列印哪些資產類別的工時成本明細。* 欄位若空白，則表示全部。","file":"fields.jsonl"};
